// 對應 Python: build_execution_api_url() 中取 projectId 的部分。
// 從 workflow 回應的 shared[0].projectId 取出 projectId，缺少就明確報錯。
const payload = $input.first().json;

const shared = payload.shared;
if (!Array.isArray(shared) || shared.length === 0) {
  throw new Error('workflow 回應缺少 shared 資料');
}

const projectId = shared[0]?.projectId ?? '';
if (!projectId) {
  throw new Error('workflow 回應缺少 projectId');
}

return [{ json: { projectId } }];

// 對應 Python: fetch_execution_log() + fetch_one_page()
// 以 cursor 自動分頁抓取 execution，抓取過程中同時做日期篩選，
// 一旦看到早於目標日期的資料就提前停止分頁（API 以新到舊排序）。
//
// 重點：每筆 execution 都會挾帶一份完整的 workflow 定義 (workflowData)，
// 佔整體回應約 85%（實測每筆 53KB → 8KB）。報表完全用不到，
// 因此在收到當下就丟掉，避免把幾十 MB 累積在記憶體裡。
const cfg = $('config').first().json;
const projectId = $input.first().json.projectId;

const baseUrl = String(cfg.n8nBaseUrl).replace(/\/+$/, '');
const apiKey = cfg.apiKey;
const workflowId = cfg.workflowId;
const timeout = Number(cfg.timeoutMs) || 60000;
const maxPages = Number(cfg.maxPages) || 200;

const targetDate = String(cfg.targetDate || '');
const targetYmd = targetDate
  ? `${targetDate.slice(0, 4)}-${targetDate.slice(4, 6)}-${targetDate.slice(6, 8)}`
  : null;

const baseExecUrl =
  `${baseUrl}/api/v1/executions?includeData=true` +
  `&workflowId=${encodeURIComponent(workflowId)}` +
  `&projectId=${encodeURIComponent(projectId)}`;

/** 只保留報表需要的欄位，丟掉 workflowData 與 n8n 內部執行狀態。 */
function slim(ex) {
  delete ex.workflowData;
  if (ex.data) {
    delete ex.data.executionData;
  }
  return ex;
}

const allExecutions = [];
let url = baseExecUrl;
let page = 1;
let stoppedEarly = false;

while (page <= maxPages) {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: { 'X-N8N-API-KEY': apiKey, accept: 'application/json' },
    json: true,
    timeout,
  });

  const executions = Array.isArray(resp?.data) ? resp.data : [];

  let stopPaging = false;
  for (const ex of executions) {
    const dateYmd = String(ex?.startedAt ?? '').slice(0, 10);

    if (targetYmd) {
      if (dateYmd === targetYmd) {
        allExecutions.push(slim(ex));
      } else if (dateYmd && dateYmd < targetYmd) {
        stopPaging = true;
      }
    } else {
      allExecutions.push(slim(ex));
    }
  }

  if (stopPaging) {
    stoppedEarly = true;
    break;
  }

  const nextCursor = resp?.nextCursor;
  if (!nextCursor) {
    break;
  }

  url = `${baseExecUrl}&cursor=${encodeURIComponent(nextCursor)}`;
  page += 1;
}

return [
  {
    json: {
      data: allExecutions,
      stats: {
        targetDate,
        pagesFetched: page,
        stoppedEarly,
        total: allExecutions.length,
      },
    },
  },
];

// 對應 Python: scrub_pii()
// customerID / phone 散落在 receive_message_API、extract_intent、
// receive_confirmation 等 20 多個節點，因此以「key 名稱」為準遞迴清除，
// 而不是只清單一條路徑，才能確保完整去個資。
//
// 註：上游 fetch_executions_paged 已把 workflowData 移除，這裡的資料
// 本來就是該節點自己從 API 組出來的，故直接就地清除即可。
// 不再做 JSON.parse(JSON.stringify(...)) 深拷貝 —— 資料量大時
// 那一步會整份多序列化一次，是壓力測試下的主要瓶頸之一。
const PII_KEYS = new Set(['customerID', 'phone']);

let removed = 0;

function scrubPii(obj) {
  if (Array.isArray(obj)) {
    for (const item of obj) scrubPii(item);
    return obj;
  }
  if (obj !== null && typeof obj === 'object') {
    for (const key of Object.keys(obj)) {
      if (PII_KEYS.has(key)) {
        delete obj[key];
        removed += 1;
      } else {
        scrubPii(obj[key]);
      }
    }
  }
  return obj;
}

const input = $input.first().json;
const data = scrubPii(input.data ?? []);

return [
  {
    json: {
      data,
      stats: {
        ...(input.stats ?? {}),
        piiKeysRemoved: removed,
        piiKeys: [...PII_KEYS],
      },
    },
  },
];
